import{_ as e,o as d,c as a,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Linear-Regression.md","filePath":"manual-en/Linear-Regression.md","lastUpdated":1785684581000}'),r={name:"manual-en/Linear-Regression.md"};function n(o,t,s,h,l,c){return d(),a("div",null,[...t[0]||(t[0]=[i(`<h4 id="_5-3-2-linear-regression" tabindex="-1">5.3.2 Linear Regression <a class="header-anchor" href="#_5-3-2-linear-regression" aria-label="Permalink to &quot;5.3.2 Linear Regression&quot;">​</a></h4><p>Linear regression is a technique used to investigate if and how a variable is linearly related to others. If a variable is found to be linearly related, then this can be used to predict future values of that variable.</p><p>In the following example, the service department of the company wanted to be able to predict the time to repair equipment, in order to improve the accuracy of their quotations. It was suggested that the time to repair might be related to the time between failures and the duty cycle of the equipment. The p-value of 0.1 was chosen for this investigation. In order to investigate this hypothesis, the <code>REGRESSION</code> command was used. This command not only tests if the variables are related, but also identifies the potential linear relationship. See <a href="./REGRESSION">REGRESSION</a>.</p><p>A first attempt includes <strong>duty_cycle</strong> :</p><pre><code>PSPP&gt; get file=&#39;/usr/local/share/pspp/examples/repairs.sav&#39;.
PSPP&gt; regression /variables = mtbf duty_cycle /dependent = mttr.
</code></pre><p>This attempt yields the following output (in part):</p><table tabindex="0"><thead><tr><th></th><th>Unstandardized Coefficients</th><th>Standardized Coefficients</th><th>t</th><th>Sig.</th><th></th></tr></thead><tbody><tr><td></td><td>B</td><td>Std. Error</td><td>Beta</td><td></td><td></td></tr><tr><td>(Constant)</td><td>10.59</td><td>3.11</td><td>.00</td><td>3.40</td><td>.002</td></tr><tr><td>Mean time between failures (months)</td><td>3.02</td><td>.20</td><td>.95</td><td>14.88</td><td>.000</td></tr><tr><td>Ratio of working to non-working time</td><td>-1.12</td><td>3.69</td><td>-.02</td><td>-.30</td><td>.763</td></tr></tbody></table><p>The coefficients in the above table suggest that the formula <em>mttr = 9.81 + 3.1 \\times mtbf + 1.09 \\times duty_cycle</em> can be used to predict the time to repair. However, the significance value for the duty_cycle coefficient is very high, which would make this an unsafe predictor. For this reason, the test was repeated, but omitting the <strong>duty_cycle</strong> variable:</p><pre><code>PSPP&gt; regression /variables = mtbf /dependent = mttr.
</code></pre><p>This second try produces the following output (in part):</p><table tabindex="0"><thead><tr><th></th><th>Unstandardized Coefficients</th><th>Standardized Coefficients</th><th>t</th><th>Sig.</th><th></th></tr></thead><tbody><tr><td></td><td>B</td><td>Std. Error</td><td>Beta</td><td></td><td></td></tr><tr><td>(Constant)</td><td>9.90</td><td>2.10</td><td>.00</td><td>4.71</td><td>.000</td></tr><tr><td>Mean time between failures (months)</td><td>3.01</td><td>.20</td><td>.94</td><td>15.21</td><td>.000</td></tr></tbody></table><p>This time, the significance of all coefficients is no higher than 0.06, suggesting that at the 0.06 level, the formula <em>mttr = 10.5 + 3.11 \\times mtbf</em> is a reliable predictor of the time to repair.</p>`,12)])])}const m=e(r,[["render",n]]);export{f as __pageData,m as default};
